import csv
import io
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, Any]:
    expected_width = 10
    text = raw_csv.lstrip("\ufeff")
    reader = csv.reader(
        io.StringIO(text, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    records = [row for row in reader if row and any(cell.strip() for cell in row)]
    if not records:
        return {"columns": [], "rows": []}

    header_index = next(
        (i for i, row in enumerate(records) if len(row) == expected_width),
        next((i for i, row in enumerate(records) if len(row) > 1), 0),
    )

    def normalize(row: list[str], width: int) -> list[str]:
        if len(row) > width:
            row = row[:width - 1] + [",".join(row[width - 1:])]
        elif len(row) < width:
            row = row + [""] * (width - len(row))
        return row

    columns = normalize(records[header_index], expected_width)
    rows = [
        normalize(row, len(columns))
        for row in records[header_index + 1:]
    ]
    return {"columns": columns, "rows": rows}
